const $ = (id) => document.getElementById(id);
const _QINDEX = {};
BANK.math.concat(BANK.rw).concat(ACT_SCIENCE).forEach((q) => { _QINDEX[q.id] = q; });
const byId = (id) => _QINDEX[id];

function bankByDiff(bankKey) {
  const out = { easy: [], medium: [], hard: [] };
  BANK[bankKey].filter((q) => !q.withheld).forEach((q) => out[q.diff].push(q));
  return out;
}
function shuffle(a) { const r = a.slice(); for (let i = r.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [r[i], r[j]] = [r[j], r[i]]; } return r; }
// Approximate share of each content domain on the real Digital SAT. ACT domains fall back to the bank's mix.
const DOMAIN_WEIGHTS = {
  "Algebra": 0.35, "Advanced Math": 0.35, "Problem-Solving & Data Analysis": 0.15, "Geometry & Trigonometry": 0.15,
  "Craft & Structure": 0.28, "Information & Ideas": 0.26, "Standard English Conventions": 0.26, "Expression of Ideas": 0.20
};
function sample(a, n, weightFn = () => 1, avoidIds = []) {
  // avoidIds: questions already in this test (e.g., module 1), so module 2 never repeats their templates.
  const avoidDedupe = new Set(avoidIds.map((id) => { const x = byId(id); return x ? x.dedupe || x.id : id; }));
  const inSet = {};
  // Rotate the whole eligible pool before repeating; older sets win ties.
  // Topic balance and adaptive skill weights apply within the freshest tier.
  let seen = {}, served = {}, lastServed = {}, recent = [], recentFamilies = [], sequence = 0;
  try {
    seen = profile.seen || {};
    served = profile.served || (profile.served = {});
    lastServed = profile.lastServed || (profile.lastServed = {});
    recent = (profile.recentQuestions || []).slice(-50);
    recentFamilies = (profile.recentFamilies || []).slice(-50);
    sequence = (profile.selectionSequence || 0) + 1;
    profile.selectionSequence = sequence;
  } catch (e) {} // Initial preview is built before the profile is loaded.
  // A question counts as used if you've seen it or any number-swapped copy of it.
  const famUses = {};
  const uses = (q) => {
    const d = q.dedupe || q.id;
    const members = typeof DEDUPE_MEMBERS !== "undefined" ? DEDUPE_MEMBERS : {};
    if (famUses[d] == null) famUses[d] = Math.max(0, ...(members[d] || [q.id]).map((id) => Math.max(seen[id] || 0, served[id] || 0)));
    return famUses[d];
  };
  const usable = a.filter((q) => !q.withheld);
  const remaining = shuffle([...new Map(usable.map((q) => [q.id, q])).values()]);
  const picked = [], counts = {}, sizes = {}, skills = {}, families = {};
  const familyOf = (q) => q.family || q.id;
  const familyHistory = (recentFamilies.length ? recentFamilies : recent.map((id) => {
    const item = a.find((q) => q.id === id);
    return item ? familyOf(item) : id;
  })).slice(-50);
  remaining.forEach((q) => { sizes[q.domain] = (sizes[q.domain] || 0) + 1; });
  const weight = (d) => DOMAIN_WEIGHTS[d] || sizes[d] / Math.max(a.length, 1);
  while (picked.length < n && remaining.length) {
    const outsideBuffer = remaining.filter((q) => !recent.includes(q.id));
    const eligible = outsideBuffer.length ? outsideBuffer : remaining.filter((q) => recent.indexOf(q.id) === Math.min(...remaining.map((item) => recent.indexOf(item.id))));
    // Prefer a different structure before using a near-duplicate, while the
    // exact 50-ID exclusion above remains the hard rule.
    const penalty = (q) => (families[familyOf(q)] || 0) * 100 +
      familyHistory.filter((f) => f === familyOf(q)).length * 5 +
      (skills[q.skill] || 0) * 2 + (q.templateVariant ? 1 : 0);
    // Hard rule: never pick a question you've done while one you haven't is available.
    const notInSet = eligible.filter((q) => !inSet[q.dedupe || q.id] && !avoidDedupe.has(q.dedupe || q.id));
    const newFamilies = notInSet.filter((q) => !families[familyOf(q)]);
    const pool2 = newFamilies.length ? newFamilies : notInSet.length ? notInSet : eligible;
    const minUses = Math.min(...pool2.map(uses));
    const unused = pool2.filter((q) => uses(q) === minUses);
    const lowestPenalty = Math.min(...unused.map(penalty));
    const tier = unused.filter((q) => penalty(q) === lowestPenalty);
    // When a template has to come back, show a copy you haven't seen rather than the same one.
    const own = (q) => Math.max(seen[q.id] || 0, served[q.id] || 0);
    const minOwn = Math.min(...tier.map(own));
    const fresh = tier.filter((q) => own(q) === minOwn);
    const oldest = Math.min(...fresh.map((q) => lastServed[q.id] || 0));
    const candidates = fresh.filter((q) => (lastServed[q.id] || 0) === oldest);
    candidates.sort((x, y) => ((counts[x.domain] || 0) / weight(x.domain)) - ((counts[y.domain] || 0) / weight(y.domain)));
    const domain = candidates[0].domain;
    const choices = candidates.filter((q) => q.domain === domain);
    let draw = Math.random() * choices.reduce((sum, q) => sum + weightFn(q), 0);
    const q = choices.find((q) => (draw -= weightFn(q)) <= 0) || choices[choices.length - 1];
    picked.push(q); inSet[q.dedupe || q.id] = true;
    const family = familyOf(q);
    families[family] = (families[family] || 0) + 1;
    skills[q.skill] = (skills[q.skill] || 0) + 1;
    familyHistory.push(family);
    if (familyHistory.length > 50) familyHistory.shift();
    recent = recent.filter((id) => id !== q.id).concat(q.id).slice(-50);
    counts[q.domain] = (counts[q.domain] || 0) + 1;
    remaining.splice(remaining.findIndex((item) => item.id === q.id), 1);
  }
  try {
    profile.recentQuestions = recent.slice(-50);
    profile.recentFamilies = familyHistory.slice(-50);
    saveProfile();
  } catch (e) {}
  return picked;
}

// Combine question usage from two devices: a question done anywhere counts as done.
function mergeQuestionLogs(other) {
  if (!other) return;
  ["seen", "served", "lastServed"].forEach((k) => {
    const mine = profile[k] = profile[k] || {};
    Object.entries(other[k] || {}).forEach(([id, n]) => { if (!(mine[id] >= n)) mine[id] = n; });
  });
  const log = profile.qlog = profile.qlog || {};
  Object.entries(other.qlog || {}).forEach(([id, o]) => {
    const m = log[id];
    if (!m) { log[id] = Object.assign({}, o); return; }
    ["shown", "answered", "correct", "last"].forEach((f) => { m[f] = Math.max(m[f] || 0, o[f] || 0); });
  });
  profile.recentQuestions = [...new Set([...(other.recentQuestions || []), ...(profile.recentQuestions || [])])].slice(-50);
  profile.activityDays = [...new Set([...(other.activityDays || []), ...(profile.activityDays || [])])].sort().slice(-730);
  refreshDailyStreak();
}
// Record a question as done the first time it's shown in an attempt. This log is what keeps
// questions from repeating, and it syncs to your account.
function markShown(q) {
  if (!q || !state.attemptId) return;
  state.shownIds = state.shownIds || [];
  if (state.shownIds.includes(q.id)) return;
  state.shownIds.push(q.id);
  const seq = profile.selectionSequence = (profile.selectionSequence || 0) + 1;
  profile.served[q.id] = (profile.served[q.id] || 0) + 1;
  profile.lastServed[q.id] = seq;
  const log = profile.qlog[q.id] = profile.qlog[q.id] || { shown: 0, answered: 0, correct: 0 };
  log.shown++; log.last = Date.now();
  profile.recentQuestions = (profile.recentQuestions || []).filter((id) => id !== q.id).concat(q.id).slice(-50);
  profile.recentFamilies = (profile.recentFamilies || []).concat(q.family || q.id).slice(-50);
  saveProfile(); save();
}
function signedIn() { try { return !!cloud.user; } catch (e) { return false; } }
function questionBankStats() {
  const fams = {};
  ALL_UNIQUE_QUESTIONS.filter((q) => !q.withheld).forEach((q) => { const f = q.dedupe || q.id; fams[f] = fams[f] || (profile.served[q.id] || 0) > 0 || (profile.seen[q.id] || 0) > 0; });
  const total = Object.keys(fams).length, done = Object.values(fams).filter(Boolean).length;
  return { total, done, fresh: total - done };
}
function weightedSampleUnique(pool, n, weightFn) {
  return sample(pool, n, weightFn);
}

function defByKey(testType, key) { return TEST_TYPES[testType].sections.find((s) => s.key === key); }
function activeKeys(cfg) {
  if (cfg.testType === "act") {
    if (cfg.actSection && cfg.actSection !== "all") return [cfg.actSection];
    return ["english", "math", "reading", "science"];
  }
  if (cfg.section === "both") return ["rw", "math"];
  return [cfg.section];
}
function satModuleMode(cfg, key) {
  const d = defByKey(cfg.testType, key);
  if (cfg.testType !== "sat" || cfg.section === "both" || !d.adaptive) return "full";
  return cfg.satModule || "full";
}
// Max questions a given section can actually deliver, given the bank size and (for SAT)
// which module the user picked — keeps "variable question count" from asking for more
// than exists.
function sectionCapacity(cfg, key) {
  const d = defByKey(cfg.testType, key);
  if (!d.adaptive) return BANK[d.bank].filter((q) => !q.withheld).length;
  const byDiff = bankByDiff(d.bank);
  const mode = satModuleMode(cfg, key);
  if (mode === "m1") return byDiff.medium.length;
  if (mode === "m2std") return byDiff.easy.length;
  if (mode === "m2hard") return byDiff.hard.length;
  return byDiff.medium.length + Math.min(byDiff.hard.length, byDiff.easy.length);
}
function maxTotalFor(cfg) { return activeKeys(cfg).reduce((s, k) => s + sectionCapacity(cfg, k), 0); }
function countsFor(cfg) {
  const keys = activeKeys(cfg);
  const out = {};
  if (cfg.testType === "act") {
    const base = Math.floor(cfg.total / keys.length);
    const rem = cfg.total % keys.length;
    keys.forEach((k, i) => { out[k] = base + (i < rem ? 1 : 0); });
  } else if (cfg.section === "both") {
    const rw = Math.ceil(cfg.total / 2);
    out.rw = rw; out.math = cfg.total - rw;
  } else {
    out[cfg.section] = cfg.total;
  }
  keys.forEach((k) => { out[k] = Math.max(1, Math.min(out[k], sectionCapacity(cfg, k))); });
  return out;
}
function buildPlan(cfg) {
  const keys = activeKeys(cfg);
  const counts = countsFor(cfg);
  const plan = {};
  keys.forEach((k) => {
    const d = defByKey(cfg.testType, k);
    const n = counts[k];
    if (d.adaptive) {
      const mode = satModuleMode(cfg, k);
      if (mode === "m1") {
        plan[k] = { adaptive: true, bank: d.bank, moduleOnly: "m1", mods: [sample(bankByDiff(d.bank).medium, n).map((q) => q.id)] };
      } else if (mode === "m2std" || mode === "m2hard") {
        const pool = bankByDiff(d.bank)[mode === "m2hard" ? "hard" : "easy"];
        plan[k] = { adaptive: true, bank: d.bank, moduleOnly: mode, presetRoute: mode === "m2hard" ? "harder" : "easier", mods: [sample(pool, n).map((q) => q.id)] };
      } else {
        const m1 = Math.ceil(n / 2), m2 = n - m1;
        plan[k] = { adaptive: true, bank: d.bank, mods: [sample(bankByDiff(d.bank).medium, m1).map((q) => q.id), null] };
      }
    } else {
      plan[k] = { adaptive: false, bank: d.bank, mods: [sample(BANK[d.bank], n).map((q) => q.id)] };
    }
  });
  return plan;
}

function newState(cfg, suppliedPlan) {
  const plan = suppliedPlan || buildPlan(cfg);
  const routes = {};
  Object.keys(plan).forEach((k) => { if (plan[k].presetRoute) routes[k] = plan[k].presetRoute; });
  return {
    v: 4, cfg, elapsed: 0, startedAt: Date.now(),
    keys: activeKeys(cfg), counts: countsFor(cfg), plan,
    routes, answers: {}, secIdx: 0, modIdx: 0, qi: 0,
    view: "start", done: false, scores: null,
    attemptId: "attempt_" + Date.now() + "_" + Math.random().toString(36).slice(2, 8)
  };
}

