        const em = (hash.match(/email=([^&]+)/) || [])[1];
        this.user = { email: em ? decodeURIComponent(em) : "Google account" };
        try { localStorage.setItem(TOKEN_KEY, JSON.stringify({ token: this.token, email: this.user.email })); } catch (e) {}
