        this.applying = true;
        const mine = { seen: profile.seen, served: profile.served, lastServed: profile.lastServed, qlog: profile.qlog, recentQuestions: profile.recentQuestions, activityDays: profile.activityDays };
        Object.keys(DEFAULT_PROFILE).forEach((k) => { if (d.profile && d.profile[k] !== undefined) profile[k] = d.profile[k]; });
        if (d.profile) Object.keys(d.profile).forEach((k) => { if (DEFAULT_PROFILE[k] === undefined && k !== "dirty" && k !== "syncedAt") profile[k] = d.profile[k]; });
        mergeQuestionLogs(mine);
