let helpHistoryItems = [];
function renderHelpHistory() {
  const list = $("helpHistoryList"), filter = $("helpHistoryFilter").value;
  const items = helpHistoryItems.filter((item) => !filter || (item.domain || item.section || "") === filter);
  list.innerHTML = "";
  if (!items.length) { const p=document.createElement("p");p.className="muted";p.textContent="No saved help matches this filter.";list.append(p);return; }
  items.forEach((item) => {
    const details=document.createElement("details");details.className="help-history-item";
    const summary=document.createElement("summary");summary.textContent=(item.skill || item.domain || item.section || "Practice help") + " · " + new Date(item.createdAt).toLocaleString();details.append(summary);
    const meta=document.createElement("p");meta.className="small muted";meta.textContent=[item.testType && item.testType.toUpperCase(),item.domain,item.category,item.model].filter(Boolean).join(" · ");details.append(meta);
    const asked=document.createElement("div");const askedTitle=document.createElement("strong");askedTitle.textContent="You asked";const askedText=document.createElement("p");askedText.textContent=item.requestText;asked.append(askedTitle,askedText);details.append(asked);
    const response=document.createElement("div");const responseTitle=document.createElement("strong");responseTitle.textContent="Tutor response";const responseText=document.createElement("pre");responseText.className="help-history-response";responseText.textContent=item.responseText;response.append(responseTitle,responseText);details.append(response);
    if (item.questionSnapshot) { const qd=document.createElement("details");const qs=document.createElement("summary");qs.textContent="Question snapshot";const qp=document.createElement("pre");qp.className="help-history-response";try{const snap=JSON.parse(item.questionSnapshot);qp.textContent=[snap.passage,snap.question,(snap.choices||[]).map((c,i)=>String.fromCharCode(65+i)+") "+c).join("\n")].filter(Boolean).join("\n\n");}catch(e){qp.textContent=item.questionSnapshot;}qd.append(qs,qp);details.append(qd); }
    const usage=document.createElement("p");usage.className="small muted";usage.textContent=item.usage && item.usage.totalTokens != null ? "Recorded usage: "+item.usage.totalTokens+" tokens" : "Token usage was not returned by Groq.";details.append(usage);
    const del=document.createElement("button");del.type="button";del.className="secondary help-delete";del.textContent="Delete this entry";del.addEventListener("click",async()=>{del.disabled=true;try{await cloud.api("help-history/"+encodeURIComponent(item.id),{method:"DELETE"});helpHistoryItems=helpHistoryItems.filter((x)=>x.id!==item.id);renderHelpHistory();}catch(e){del.disabled=false;setAuthMsg(e.msg||"Could not delete that entry.",true);}});details.append(del);list.append(details);
  });
}
