    while (stack.length) {
      const [r, cc] = stack.pop();
      const nbs = [[0, -1], [0, 1], [1, 0], [-1, 0], [r % 2 ? -1 : 1, -1], [r % 2 ? -1 : 1, 1]];
      for (const [dr, dc] of nbs) { const nr = r + dr, nc = cc + dc; if (nr >= 0 && nr < this.grid.length && nc >= 0 && nc < this.cols && this.grid[nr][nc] >= 0 && !attached.has(nr + ',' + nc)) { attached.add(nr + ',' + nc); stack.push([nr, nc]); } }
    }
    let dropped = 0;
    for (let row = 0; row < this.grid.length; row++) for (let c = 0; c < this.cols; c++) if (this.grid[row][c] >= 0 && !attached.has(row + ',' + c)) { this.grid[row][c] = -1; dropped++; }
    return dropped;
