      ctx.beginPath(); ctx.moveTo(a.r.x, a.r.y); ctx.lineTo(a.cr.x, a.cr.y); ctx.lineTo(b.cr.x, b.cr.y); ctx.lineTo(b.r.x, b.r.y); ctx.closePath(); ctx.fill();
