      curbsR: RacingGL.wallStrip(centers, { side: 1, off: (q) => q.half, height: () => 0.1, color: (i) => (i % 2 ? white : curb) }),
      wallsL: RacingGL.wallStrip(centers, { side: -1, off, height, color: () => wall }),
